INSERT INTO "Question" ("id","prompt","options","correctIndex","explanation","difficulty","answers","hint","order","courseId","levelId","createdAt") VALUES
('q_prir-1-rocni-obdobi_0','Kolik ročních období je v roce?',ARRAY['4','3','2','5']::TEXT[],0,'Jaro, léto, podzim a zima.',1,ARRAY[]::TEXT[],NULL,0,'c_prir-1-rocni-obdobi',NULL,NOW()),
('q_prir-1-rocni-obdobi_1','Které roční období je nejteplejší?',ARRAY['Zima','Jaro','Léto','Podzim']::TEXT[],2,'V létě je nejtepleji.',1,ARRAY[]::TEXT[],NULL,1,'c_prir-1-rocni-obdobi',NULL,NOW()),
('q_prir-1-rocni-obdobi_2','Které roční období je nejchladnější?',ARRAY['Jaro','Léto','Zima','Podzim']::TEXT[],2,'V zimě mrzne a sněží.',1,ARRAY[]::TEXT[],NULL,2,'c_prir-1-rocni-obdobi',NULL,NOW()),
('q_prir-1-rocni-obdobi_3','Kdy opadává listí ze stromů?',ARRAY['Na podzim','V létě','V zimě','Na jaře']::TEXT[],0,'Na podzim stromy shazují listí.',2,ARRAY[]::TEXT[],NULL,3,'c_prir-1-rocni-obdobi',NULL,NOW()),
('q_prir-1-rocni-obdobi_4','Kdy kvetou první květiny, třeba sněženky?',ARRAY['V létě','Na jaře','V zimě','Na podzim']::TEXT[],1,'Sněženky kvetou brzy zjara.',2,ARRAY[]::TEXT[],NULL,4,'c_prir-1-rocni-obdobi',NULL,NOW()),
('q_prir-1-rocni-obdobi_5','Kdy bývá sníh?',ARRAY['Na podzim','V létě','V zimě','Na jaře']::TEXT[],2,'Sníh padá v zimě.',2,ARRAY[]::TEXT[],NULL,5,'c_prir-1-rocni-obdobi',NULL,NOW()),
('q_prir-1-rocni-obdobi_6','Které roční období následuje po jaru?',ARRAY['Zima','Podzim','Jaro','Léto']::TEXT[],3,'Jaro, léto, podzim, zima.',3,ARRAY[]::TEXT[],NULL,6,'c_prir-1-rocni-obdobi',NULL,NOW()),
('q_prir-1-rocni-obdobi_7','Co si vezmeš na sebe v zimě?',ARRAY['Plavky','Sandály','Šortky','Čepici a rukavice']::TEXT[],3,'V zimě se teple oblékáme.',3,ARRAY[]::TEXT[],NULL,7,'c_prir-1-rocni-obdobi',NULL,NOW()),
('q_prir-1-rocni-obdobi_8','Co si vezmeš do deště?',ARRAY['Lyže','Plavky','Pláštěnku nebo deštník','Lopatku']::TEXT[],2,'Před deštěm nás chrání deštník.',3,ARRAY[]::TEXT[],NULL,8,'c_prir-1-rocni-obdobi',NULL,NOW()),
('q_prir-1-rocni-obdobi_9','Kdy dozrává ovoce, třeba jablka a hrušky?',ARRAY['Na konci léta a na podzim','Uprostřed zimy','Brzy zjara','V zimě']::TEXT[],0,'Jablka dozrávají koncem léta a na podzim.',4,ARRAY[]::TEXT[],NULL,9,'c_prir-1-rocni-obdobi',NULL,NOW()),
('q_prir-1-rocni-obdobi_10','Kdy se vracejí stěhovaví ptáci?',ARRAY['Nikdy','V zimě','Na podzim','Na jaře']::TEXT[],3,'Zjara se stěhovaví ptáci vracejí domů.',4,ARRAY[]::TEXT[],NULL,10,'c_prir-1-rocni-obdobi',NULL,NOW()),
('q_prir-1-rocni-obdobi_11','Co dělá ježek v zimě?',ARRAY['Spí zimní spánek','Pracuje','Staví hnízdo','Plave']::TEXT[],0,'Ježek přečká zimu ve spánku.',4,ARRAY[]::TEXT[],NULL,11,'c_prir-1-rocni-obdobi',NULL,NOW()),
('q_prir-1-rocni-obdobi_12','Proč jsou v létě delší dny než v zimě?',ARRAY['Země se zastaví','Slunce je déle na obloze','Hodiny jdou rychleji','Měsíc svítí víc']::TEXT[],1,'V létě je slunce na obloze déle.',5,ARRAY[]::TEXT[],NULL,12,'c_prir-1-rocni-obdobi',NULL,NOW()),
('q_prir-1-rocni-obdobi_13','Který měsíc je letní?',ARRAY['Červenec','Říjen','Leden','Prosinec']::TEXT[],0,'Červenec je uprostřed léta.',5,ARRAY[]::TEXT[],NULL,13,'c_prir-1-rocni-obdobi',NULL,NOW()),
('q_prir-1-rocni-obdobi_14','Který měsíc je zimní?',ARRAY['Leden','Srpen','Červen','Červenec']::TEXT[],0,'Leden je zimní měsíc.',5,ARRAY[]::TEXT[],NULL,14,'c_prir-1-rocni-obdobi',NULL,NOW()),
('q_prir-1-pece-o-mazlicka_0','Co potřebuje pes ke svému životu?',ARRAY['Jen kost','Jídlo, vodu a lásku','Jen hračky','Jen pohádky']::TEXT[],1,'Pes potřebuje péči.',1,ARRAY[]::TEXT[],NULL,0,'c_prir-1-pece-o-mazlicka',NULL,NOW()),
('q_prir-1-pece-o-mazlicka_1','Kdo se stará o domácího mazlíčka?',ARRAY['Ten, kdo ho má','Nikdo','Pošťák','Soused']::TEXT[],0,'Majitel zvířete za něj odpovídá.',1,ARRAY[]::TEXT[],NULL,1,'c_prir-1-pece-o-mazlicka',NULL,NOW()),
('q_prir-1-pece-o-mazlicka_2','Co pije kočka?',ARRAY['Vodu a mléko pro koťata','Kávu','Limonádu','Šťávu']::TEXT[],0,'Kočka pije vodu.',1,ARRAY[]::TEXT[],NULL,2,'c_prir-1-pece-o-mazlicka',NULL,NOW()),
('q_prir-1-pece-o-mazlicka_3','Kde spí pes?',ARRAY['V lednici','V aktovce','V pelíšku','Na stromě']::TEXT[],2,'Pes má svůj pelíšek.',2,ARRAY[]::TEXT[],NULL,3,'c_prir-1-pece-o-mazlicka',NULL,NOW()),
('q_prir-1-pece-o-mazlicka_4','Co potřebuje akvarijní rybka?',ARRAY['Čistou vodu a krmení','Trávu','Sníh','Písek bez vody']::TEXT[],0,'Rybka žije ve vodě.',2,ARRAY[]::TEXT[],NULL,4,'c_prir-1-pece-o-mazlicka',NULL,NOW()),
('q_prir-1-pece-o-mazlicka_5','Čím se krmí králík?',ARRAY['Čokoládou','Masem','Chipsy','Mrkví a senem']::TEXT[],3,'Králík je býložravec.',2,ARRAY[]::TEXT[],NULL,5,'c_prir-1-pece-o-mazlicka',NULL,NOW()),
('q_prir-1-pece-o-mazlicka_6','Kdy venčíme psa?',ARRAY['Jen v zimě','Jednou za měsíc','Několikrát denně','Nikdy']::TEXT[],2,'Pes potřebuje pohyb a venek.',3,ARRAY[]::TEXT[],NULL,6,'c_prir-1-pece-o-mazlicka',NULL,NOW()),
('q_prir-1-pece-o-mazlicka_7','Co dělat, když nás zvíře kousne?',ARRAY['Utéct a nic neříct','Říct dospělému a ránu ošetřit','Dát obklad ze sněhu','Nic']::TEXT[],1,'Pomoc dospělého a ošetření rány.',3,ARRAY[]::TEXT[],NULL,7,'c_prir-1-pece-o-mazlicka',NULL,NOW()),
('q_prir-1-pece-o-mazlicka_8','Proč chodí pes k veterináři?',ARRAY['Na zmrzlinu','Na procházku','Kvůli hračkám','Aby byl zdravý (očkování)']::TEXT[],3,'Veterinář pečuje o zdraví zvířat.',3,ARRAY[]::TEXT[],NULL,8,'c_prir-1-pece-o-mazlicka',NULL,NOW()),
